mapper.select:
SELECT IDX, DOC_NO, TITLE, DOC_TYPE, TYPE_NAME, STATUS_TXT FROM ( /* PRODUCT */ SELECT p.PRODUCT_IDX AS IDX, p.DOC_NO AS DOC_NO, p.TITLE AS TITLE, 'PROD' AS DOC_TYPE, '제품완료보고서' AS TYPE_NAME, FN_GET_CODE_NAME('DOC_STATUS', p.STATUS) AS STATUS_TXT FROM lab_product p WHERE p.DOC_OWNER = #{userId} and p.IS_LAST = 'Y' and p.IS_DELETE = 'N'
UNION ALL
/* MENU */ SELECT m.MENU_IDX AS IDX, m.DOC_NO AS DOC_NO, m.TITLE AS TITLE, 'MENU' AS DOC_TYPE, '메뉴완료보고서' AS TYPE_NAME, FN_GET_CODE_NAME('DOC_STATUS', m.STATUS) AS STATUS_TXT FROM lab_menu m WHERE m.DOC_OWNER = #{userId} and m.IS_LAST = 'Y' and m.IS_DELETE = 'N'
UNION ALL
/* DESIGN (DOC_NO 없음, TITLE 없으면 PRODUCT_NAME) */ SELECT d.DESIGN_IDX AS IDX, d.DOC_NO AS DOC_NO, COALESCE(d.TITLE, d.PRODUCT_NAME) AS TITLE, 'DESIGN' AS DOC_TYPE, '상품설계변경보고서' AS TYPE_NAME, FN_GET_CODE_NAME('DOC_STATUS', d.STATUS) AS STATUS_TXT FROM lab_design d WHERE d.DOC_OWNER = #{userId} and d.IS_LAST = 'Y' and d.IS_DELETE = 'N'
UNION ALL
/* SENSE QUALITY REPORT (DOC_NO 없음, TITLE 있음) */ SELECT r.REPORT_IDX AS IDX, NULL AS DOC_NO, r.TITLE AS TITLE, 'REPORT' AS DOC_TYPE, '관능/품질평가보고서' AS TYPE_NAME, FN_GET_CODE_NAME('DOC_STATUS', r.STATUS) AS STATUS_TXT FROM lab_sense_quality_report r WHERE r.DOC_OWNER = #{userId} and r.IS_DELETE = 'N'
UNION ALL
/* BUSINESS TRIP PLAN (DOC_NO 없음) */ SELECT bp.PLAN_IDX AS IDX, NULL AS DOC_NO, bp.TITLE AS TITLE, 'PLAN' AS DOC_TYPE, '출장계획보고서' AS TYPE_NAME, FN_GET_CODE_NAME('DOC_STATUS', bp.STATUS) AS STATUS_TXT FROM lab_business_trip_plan bp WHERE bp.DOC_OWNER = #{userId} and bp.IS_DELETE = 'N'
UNION ALL
/* BUSINESS TRIP (DOC_NO 없음) */ SELECT bt.TRIP_IDX AS IDX, NULL AS DOC_NO, bt.TITLE AS TITLE, 'TRIP' AS DOC_TYPE, '출장결과보고서' AS TYPE_NAME, FN_GET_CODE_NAME('DOC_STATUS', bt.STATUS) AS STATUS_TXT FROM lab_business_trip bt WHERE bt.DOC_OWNER = #{userId} and bt.IS_DELETE = 'N'
UNION ALL
/* MARKET RESEARCH (DOC_NO 없음) */ SELECT mr.RESEARCH_IDX AS IDX, NULL AS DOC_NO, mr.TITLE AS TITLE, 'RESEARCH' AS DOC_TYPE, '시장조사결과보고서' AS TYPE_NAME, FN_GET_CODE_NAME('DOC_STATUS', mr.STATUS) AS STATUS_TXT FROM lab_market_research mr WHERE mr.DOC_OWNER = #{userId} and mr.IS_DELETE = 'N'
UNION ALL
/* NEW PRODUCT RESULT (DOC_NO 없음) */ SELECT nr.RESULT_IDX AS IDX, NULL AS DOC_NO, nr.TITLE AS TITLE, 'RESULT' AS DOC_TYPE, '메뉴품질점검결과보고서' AS TYPE_NAME, FN_GET_CODE_NAME('DOC_STATUS', nr.STATUS) AS STATUS_TXT FROM lab_new_product_result nr WHERE nr.DOC_OWNER = #{userId} and nr.IS_DELETE = 'N'
UNION ALL
/* CHEMICAL TEST (DOC_NO 없음, TITLE 없으면 PRODUCT_NAME) */ SELECT ct.CHEMICAL_IDX AS IDX, NULL AS DOC_NO, ct.PRODUCT_NAME AS TITLE, 'CHEMICAL' AS DOC_TYPE, '이화학검사의뢰서' AS TYPE_NAME, FN_GET_CODE_NAME('DOC_STATUS', ct.STATUS) AS STATUS_TXT FROM lab_chemical_test ct WHERE ct.DOC_OWNER = #{userId} and ct.IS_DELETE = 'N'
UNION ALL
/* PACKAGE INFO (DOC_NO 있음, TITLE 없으면 PRODUCT_NAME) */ SELECT pk.PACKAGE_IDX AS IDX, pk.DOC_NO AS DOC_NO, pk.PRODUCT_NAME AS TITLE, 'PACKAGE' AS DOC_TYPE, '표시사항기재양식' AS TYPE_NAME, FN_GET_CODE_NAME('DOC_STATUS', pk.STATUS) AS STATUS_TXT FROM lab_package_info pk WHERE pk.DOC_OWNER = #{userId} and pk.IS_LAST = 'Y' and pk.IS_DELETE = 'N'
UNION ALL
/* RECIPE INFO */ SELECT rp.RECIPE_IDX AS IDX, rp.DOC_NO AS DOC_NO, rp.PRODUCT_NAME AS TITLE, 'RECIPE' AS DOC_TYPE, '사전원가서' AS TYPE_NAME, FN_GET_CODE_NAME('DOC_STATUS', rp.STATUS) AS STATUS_TXT FROM lab_recipe rp WHERE rp.DOC_OWNER = #{userId} and rp.IS_LAST = 'Y' and rp.IS_DELETE = 'N'
UNION ALL
/* BOARD NOTICE (DOC_NO 없음) */ SELECT bn.BNOTICE_IDX AS IDX, NULL AS DOC_NO, bn.TITLE AS TITLE, 'NOTICE' AS DOC_TYPE, '공지사항' AS TYPE_NAME, case bn.TYPE when 'I' then '공지' when 'N' then '일반' else '' end AS STATUS_TXT FROM lab_board_notice bn WHERE bn.REG_USER = #{userId} and bn.IS_DELETE = 'N' ) U ORDER BY DOC_TYPE, IDX

